uses Graph3D;

function MultipleClones(c: Object3D; N: integer): Group3D;
begin
  var g := Group(c);
  loop N-1 do
  begin
    c := c.Clone;
    c.MoveByX(-1.5);
    if c is ObjectWithMaterial3D then 
      (c as ObjectWithMaterial3D).Color := RandomColor;
    g.AddChild(c);
  end;
  Result := g;
end;

begin
  HideObjects;
