  var c1 := Cone(6.75,0,5,1.5,0.4,RandomColor);
  var g := MultipleClones(c,10);
  var gp := MultipleClones(c1,10);
  var gg := Group(g,b,gp);
  var g1 := gg.Clone.MoveByY(6);
  var g2 := gg.Clone.MoveByY(-6);
  gg.Rotate(OrtZ,90);
  var g3 := gg.Clone.MoveByX(-6);
  gg.MoveByX(6);
  var ggg := Group(gg,g1,g2,g3);
